package solution

import (
	"sync"
	"testing"
)

func TestConcurrentInc(t *testing.T) {
	c := &SafeCounter{}
	var wg sync.WaitGroup
	for i := 0; i < 1000; i++ {
		wg.Add(1)
		go func() { defer wg.Done(); c.Inc() }()
	}
	wg.Wait()
	if c.Value() != 1000 {
		t.Fatalf("expected 1000, got %d", c.Value())
	}
}
